DO $$ DECLARE v_def text; BEGIN SELECT pg_get_functiondef('public.dp_documento_requisitos_seed(uuid)'::regprocedure) INTO v_def; IF position('(_company_id,''autorizacao_menor''' IN v_def)=0 OR position('(_company_id,''cnh_valida''' IN v_def)=0 THEN RAISE EXCEPTION 'Lista padrao alterada: revisar'; END IF; v_def:=replace(v_def, '(_company_id,''autorizacao_menor'',''Autorização judicial e comprovante escolar (menor)'',''Menores de 18 anos e aprendizes.'',''situacao'',''obrigatorio'',''menor'',''admissao'',''unica'',NULL,30,false,false,NULL,true,150,false),', '(_company_id,''comprovante_escolar_menor'',''Comprovante escolar do candidato menor'',''Comprova matrícula escolar do candidato menor; não é a declaração escolar dos dependentes.'',''situacao'',''obrigatorio'',''menor'',''admissao'',''unica'',NULL,30,false,false,NULL,true,150,false), (_company_id,''autorizacao_judicial_menor'',''Autorização judicial'',''Somente quando decisão judicial específica exigir.'',''situacao'',''opcional'',''menor'',''admissao'',''unica'',NULL,30,false,false,NULL,true,151,false),'); EXECUTE v_def; END $$;